(** val dec_str_fuel : nat -> nat -> string **)

let rec dec_str_fuel fuel n =
  match fuel with
  | O -> ""
  | S f ->
    if Nat.ltb n (S (S (S (S (S (S (S (S (S (S O))))))))))
    then (* If this appears, you're using String internals. Please don't *)
  (fun (c, s) -> String.make 1 c ^ s)

           ((digit_char n), "")
    else (^)
           (dec_str_fuel f
             (Nat.div n (S (S (S (S (S (S (S (S (S (S O))))))))))))
           ((* If this appears, you're using String internals. Please don't *)
  (fun (c, s) -> String.make 1 c ^ s)

           ((digit_char
              (Nat.modulo n (S (S (S (S (S (S (S (S (S (S O)))))))))))),
           ""))

(** val dec_str : nat -> string **)

let dec_str n =
  dec_str_fuel (S n) n

