(** val roman_acc : string -> nat -> nat -> nat **)

let rec roman_acc s prev total =
  (* If this appears, you're using String internals. Please don't *)
 (fun f0 f1 s ->
    let l = String.length s in
    if l = 0 then f0 () else f1 (String.get s 0) (String.sub s 1 (l-1)))

    (fun _ -> total)
    (fun c s' ->
    let n = roman_digit c in
    roman_acc s' n (if Nat.ltb n prev then sub total n else add total n))
    s

(** val roman_value : string -> nat **)

let roman_value s =
  roman_acc (rev_string s) O O

